cat > /tmp/opencode/test-dispatcher.js <<'EOF'
const assert = require('assert');
const { deliver } = require('/workspace/src/dispatcher.js');

(async () => {
  // 1. Success on first try returns the response.
  {
    const io = { post: async () => ({ status: 200, body: 'ok' }) };
    const res = await deliver(io, { id: 1 });
    assert.strictEqual(res.status, 200);
  }
  console.log('1. immediate success: ok');

  // 2. Intermittent 502 then 200 -> retries and returns 200.
  {
    let calls = 0;
    const io = {
      post: async () => {
        calls += 1;
        if (calls === 1) return { status: 502 };
        return { status: 200 };
      },
    };
    const res = await deliver(io, { id: 2 });
    assert.strictEqual(calls, 2);
    assert.strictEqual(res.status, 200);
  }
  console.log('2. 502 then success: ok');

  // 3. Network error then success -> retries.
  {
    let calls = 0;
    const io = {
      post: async () => {
        calls += 1;
        if (calls === 1) { const e = new Error('socket hang up'); e.code = 'ECONNRESET'; throw e; }
        return { status: 204 };
      },
    };
    const res = await deliver(io, { id: 3 });
    assert.strictEqual(calls, 2);
    assert.strictEqual(res.status, 204);
  }
  console.log('3. network error then success: ok');

  // 4. 4xx is NOT retried.
  {
    let calls = 0;
    const io = {
      post: async () => { calls += 1; return { status: 400 }; },
    };
    const res = await deliver(io, { id: 4 });
    assert.strictEqual(calls, 1);
    assert.strictEqual(res.status, 400);
  }
  console.log('4. 4xx not retried: ok');

  // 5. Persistent 502 exhausts budget and returns last response.
  {
    let calls = 0;
    const io = { post: async () => { calls += 1; return { status: 502 }; } };
    const res = await deliver(io, { id: 5 });
    assert.strictEqual(calls, 3); // default maxAttempts
    assert.strictEqual(res.status, 502);
  }
  console.log('5. persistent 502 bounded retries: ok');

  // 6. Persistent network error throws after budget.
  {
    let calls = 0;
    const io = {
      post: async () => { calls += 1; const e = new Error('ECONNREFUSED'); e.code = 'ECONNREFUSED'; throw e; },
    };
    await assert.rejects(() => deliver(io, { id: 6 }), /ECONNREFUSED/);
    assert.strictEqual(calls, 3);
  }
  console.log('6. persistent network error throws: ok');

  // 7. Non-network error is not retried.
  {
    let calls = 0;
    const io = {
      post: async () => { calls += 1; throw new Error('boom'); },
    };
    await assert.rejects(() => deliver(io, { id: 7 }), /boom/);
    assert.strictEqual(calls, 1);
  }
  console.log('7. non-network error not retried: ok');

  // 8. statusCode-style response also handled.
  {
    let calls = 0;
    const io = {
      post: async () => { calls += 1; if (calls === 1) return { statusCode: 503 }; return { statusCode: 200 }; },
    };
    const res = await deliver(io, { id: 8 });
    assert.strictEqual(res.statusCode, 200);
  }
  console.log('8. statusCode response retried: ok');

  // 9. Retry-After header respected (bounded).
  {
    let calls = 0;
    const io = {
      post: async () => {
        calls += 1;
        if (calls === 1) return { status: 429, headers: { 'retry-after': '1' } };
        return { status: 200 };
      },
    };
    const res = await deliver(io, { id: 9 });
    assert.strictEqual(res.status, 200);
  }
  console.log('9. retry-after respected: ok');

  // 10. custom maxAttempts option works.
  {
    let calls = 0;
    const io = { post: async () => { calls += 1; return { status: 502 }; } };
    const res = await deliver(io, { id: 10 }, { maxAttempts: 2 });
    assert.strictEqual(calls, 2);
    assert.strictEqual(res.status, 502);
  }
  console.log('10. custom maxAttempts: ok');

  console.log('\nAll tests passed.');
})().catch((e) => { console.error('FAILED:', e); process.exit(1); });
EOF
